"""A relay-aimed recall outlives post_month's next general's task (#4533).

A whole-island picker re-aims a camp at the back-half relay cell and sends B.
While that picker closes (``relay_menu_waits``) and while leg one is being
dead-reckoned, the aim and the road live in the one ``flow.recall`` dict. The
monthly status handler used to replace it from another general's task at its
task-jump handoff, so いどう was never chosen.
"""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[2] / 'src'))

from docich.hanjuku_speedrun.hanjuku.flows import post_month_status as post
from docich.hanjuku_speedrun.hanjuku.os_layer.screen import Screen
from docich.hanjuku_speedrun.hanjuku.state.regions import flow as _flow


def memory():
    mem = {'chapter': 11, 'month': '2-6', 'tick': 100, 'gold': 250,
           '_records': [],
           'month_sorties': {'scope': [11, '2-6'], 'launches': 1}}
    post.arm(mem)
    return mem


def test_a_relay_aimed_recall_is_not_replaced_by_the_next_recall_task():
    mem = memory()
    state = mem['post_month_status']
    job = {'kind': 'recall', 'name': 'どうし'}
    state.update(stage='task_jump', tasks=[], job=job)
    relay = _flow(mem)['recall'] = {
        'stage': 'menu', 'target': [140, 112],
        'camp_world': [638, 348],
        'relay': {'cell': [508, 264], 'hub': 'タタール'},
        'relay_menu_waits': 2}
    field = Screen([], None, '', kind='map', cursor=(140, 112))

    assert post.step(field, mem, None) == []
    assert _flow(mem).get('recall') is relay      # same dict, not a fresh recall
    assert state['job'] == job
    assert state['stage'] == 'task_jump'
    assert any(r['decision'] == 'post_month_recall_held_for_relay'
               for r in mem['_records'])

    # The hold is narrow: once the relay flow is gone the same job proceeds.
    _flow(mem).pop('recall', None)
    post.step(field, mem, None)
    started = _flow(mem).get('recall')
    assert isinstance(started, dict) and started.get('general') == 'どうし'
    assert state['stage'] == 'wait_recall'
